STATIC_ABILITY.CONTINUOUS_ACTION:
if EffectSource() ~= nil then local filter = ClearFilter()
local subfilter = filter:AddSubFilter_Or() subfilter:Add( FE_SUBTYPE, OP_IS, CREATURE_TYPE_DEMON ) subfilter:Add( FE_SUBTYPE, OP_IS, CREATURE_TYPE_DRAGON ) EffectSource():Protection()
end

TRIGGERED_ABILITY.TRIGGER:
if EffectSource() ~= nil then
	return TriggerObject() == EffectSource():GetParent()
end
